-- 拆分已交付操作，固定权限码与真实执行点对应；不创建未实现能力。
-- 一次性按原宽权限逐角色复制，保持已有权限范围；未持有来源权限的角色不得自动增权。
-- 角色版本推进，使变更可追溯并使已有权限快照失效。
UPDATE access_role SET version=version+1 WHERE scope_type='PLATFORM' AND id IN(SELECT role_id FROM access_role_permission WHERE permission_id IN(SELECT id FROM access_permission WHERE resource IN('tenant.invitation','integration.client','audit.entry','platform.task') OR action IN('revoke_sessions','reset_password','enable','remove')));

